import sys
from openpyxl import load_workbook

path = "budget.xlsx"
wb = load_workbook(path, data_only=True)
print("Sheets:", wb.sheetnames)

def looks_like_amount(h):
    if not isinstance(h, str):
        return False
    h = h.strip().lower()
    return any(k in h for k in ("amount", "cost", "expense", "spend", "value", "price", "$", "total"))

grand_total = 0.0
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (max_row={ws.max_row}, max_col={ws.max_column}) ===")
    rows = list(ws.iter_rows(values_only=True))
    for i, row in enumerate(rows, start=1):
        if any(v is not None for v in row):
            print(i, row)

    # Per-sheet fallback: sum all numeric cells
    sheet_num_total = 0.0
    for row in rows:
        for v in row:
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                sheet_num_total += v
    print(f"--> Sum of all numeric cells in sheet '{name}': {sheet_num_total}")
    grand_total += sheet_num_total

print(f"\nGRAND TOTAL (all numeric cells, all sheets): {grand_total}")

